import{_ as s,o as e,c as p,am as n}from"./chunks/framework._FJXuPhs.js";const h=JSON.parse('{"title":"消息队列_Kafka_安装与使用","description":"","frontmatter":{"title":"消息队列_Kafka_安装与使用","excerpt":"消息队列_Kafka_安装与使用","date":"2024-02-08 19:02:07","updated":"2024-02-08 19:02:07"},"headers":[],"relativePath":"中间件/中间件 - 消息队列/消息队列_Kafka/消息队列_Kafka_安装与使用.md","filePath":"中间件/中间件 - 消息队列/消息队列_Kafka/消息队列_Kafka_安装与使用.md","lastUpdated":null}'),t={name:"中间件/中间件 - 消息队列/消息队列_Kafka/消息队列_Kafka_安装与使用.md"};function o(i,a,l,c,r,k){return e(),p("div",null,[...a[0]||(a[0]=[n(`<p>系统环境是：Centos 7</p><p>参考：</p><ul><li><a href="https://www.cnblogs.com/paopaoT/p/17464032.html" target="_blank" rel="noreferrer">https://www.cnblogs.com/paopaoT/p/17464032.html</a></li></ul><p>Kafka 是一个分布式的基于发布/订阅模式的消息中间件，在业界主要应用于大数据实时流式计算领域，起解耦合和削峰填谷的作用。</p><p>在 Kafka 2.8 之前，Kafka 其重度依赖于 Zookeeper</p><p>安装操作： <a href="https://www.cnblogs.com/paopaoT/p/17461562.html" target="_blank" rel="noreferrer">https://www.cnblogs.com/paopaoT/p/17461562.html</a></p><p>这里跳过上述操作，直接使用 docker 安装 kafka</p><h3 id="一、kafka-服务的安装与测试使用步骤" tabindex="-1">一、Kafka 服务的安装与测试使用步骤 <a class="header-anchor" href="#一、kafka-服务的安装与测试使用步骤" aria-label="Permalink to &quot;一、Kafka 服务的安装与测试使用步骤&quot;">​</a></h3><p>安装手册： <a href="https://developer.aliyun.com/article/1318521" target="_blank" rel="noreferrer">https://developer.aliyun.com/article/1318521</a></p><p>拉取 ZooKeeper</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker pull wurstmeister/zookeeper</span></span></code></pre></div><p>改一下挂载文件目录</p><p>启动 ZooKeeper 服务</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#创建对应的目录来挂载Zookeeper,个人是放在 /root/RunEnvironment/zookeeper 目录下</span></span>
<span class="line"><span></span></span>
<span class="line"><span>docker run -d --name zookeeper  -p 2181:2181 -v /root/RunEnvironment/zookeeper:/data --restart always wurstmeister/zookeeper</span></span></code></pre></div><ul><li><ul><li>p 2181:2181 # 对端口进行映射，将本地2181端口映射到容器内部的2181端口</li></ul></li><li>– name # 设置创建的容器名称 -v # 将本地目录(文件)挂载到容器指定目录；</li><li>– restart always # 始终重新启动zookeeper</li></ul><p>拉取Kafka</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker pull wurstmeister/kafka</span></span></code></pre></div><p>启动 Kafka</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker run -d --name kafka -p 9092:9092 -e KAFKA_BROKER_ID=0 -e KAFKA_ZOOKEEPER_CONNECT=【ZooKeeper地址】:2181 -e KAFKA_ADVERTISED_LISTENERS=PLAINTEXT://【kafka地址】:9092 -e KAFKA_LISTENERS=PLAINTEXT://0.0.0.0:9092 wurstmeister/kafka</span></span></code></pre></div><p>实际使用的时候是讲两个服务的地址都改为了服务器的IP地址，然后启动运行</p><p>打开 Portainer 中的容器管理，选择进入容器</p><p>测试：</p><p>创建一个名为“testTopic”的topic，它有一个分区和一个副本</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 创建主题</span></span>
<span class="line"><span>kafka-topics.sh --create --zookeeper zookeeper地址:2181 --replication-factor 1 --partitions 1 --topic testTopic</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 列出所有主题来验证创建成功</span></span>
<span class="line"><span>kafka-topics.sh --list --zookeeper zookeeper地址:2181</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#发送消息</span></span>
<span class="line"><span>kafka-console-producer.sh --broker-list kafka地址:9092 --topic testTopic</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#启动一个 consumer,将消息转储到标准输出</span></span>
<span class="line"><span>#从指定的Kafka集群的\`testTopic\`主题中，从最开始的消息起，消费并在控制台显示所有消息</span></span>
<span class="line"><span>kafka-console-consumer.sh --bootstrap-server kafka地址:9092 --topic testTopic --from-beginning</span></span></code></pre></div><ul><li><code>--from-beginning</code>：这个参数告诉消费者从主题的起始位置开始消费消息。如果不指定此参数，那么消费者将从最新的消息开始消费，即只消费自消费者启动之后发布到主题的新消息。</li></ul><p>实际运行的时候需要讲上述命令的IP地址换为服务器的地址：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kafka-topics.sh --create --zookeeper 192.168.31.43:2181 --replication-factor 1 --partitions 1 --topic testTopic</span></span>
<span class="line"><span>kafka-topics.sh --list --zookeeper 192.168.31.43:2181</span></span>
<span class="line"><span>kafka-console-producer.sh --broker-list 192.168.31.43:9092 --topic testTopic</span></span>
<span class="line"><span>kafka-console-consumer.sh --bootstrap-server 192.168.31.43:9092 --topic testTopic --from-beginning</span></span></code></pre></div><p>还看到一种方式是通过 docker-compose.yml 的操作讲上述串联起来，后续有兴趣可以研究一下。</p>`,28)])])}const u=s(t,[["render",o]]);export{h as __pageData,u as default};
